chinery.", "violation_refs": ["V1"], "postcondition_refs": ["P1"], "depends_on": []}], "postconditions": [{"id": "P1", "statement": "During each valid configuration reload and immediately after each successful reload response, the production groups API contains all active alert groups instead of temporarily omitting them.", "requirement_refs": ["O1"], "obligation_refs": ["A1"], "relation_refs": ["R1", "R2", "R3", "R4", "R5"], "planned_check": "Observe the production groups HTTP API with 2ms sampling during twenty valid reloads and at each reload return; require all 2048 injected active alert group names present at each successful during-reload sample and at each reload return.", "check_scope": "Local production process HTTP API, twenty valid reloads with 2048 injected groups; sampled during reload and immediate return only.", "check_coverage": "ALL_OF", "coverage_rationale": "groups.visible_during_reload covers the during-reload sampled instants; groups.visible_at_reload_return covers the immediate post-return instances. Together they cover the concrete during-and-immediately-after reload statement. They do not cover unsampled instants or distributed convergence.", "verification_kind": "PUBLIC_BEHAVIOR", "behavior_check_refs": ["alertmanager-reload-v4:groups.visible_during_reload", "alertmanager-reload-v4:groups.visible_at_reload_return"], "verification_scope": {"scenario": "method-alertmanager-reload-v4"}, "stable_obligation_keys": ["OB-2758c0e9950249515f883dfa"]}], "preserve_constraints": [], "open_obligations": [{"id": "OPEN-UNSAMPLED", "outcome_id": "O1", "obligation_refs": ["A1"], "statement": "The requirement holds at instants between the 2ms samples and under distributed convergence during a reload.", "reason": "The public probe boundary explicitly excludes unsampled instants and distributed convergence; the sampled continuity checks cannot prove this.", "check_coverage": "NECESSARY_ONLY", "coverage_rationale": "No public check exhausts unsampled instants or 